function wmsUrl(layer,{west,east,south,north}){const u=new URL(GIBS_WMS);u.search=new URLSearchParams({service:'WMS',version:'1.1.1',request:'GetMap',styles:'',layers:layer,srs:'EPSG:4326',bbox:`${west},${south},${east},${north}`,width:'1200',height:'960',format:'image/jpeg',transparent:'false'}).toString();return u.href}
async function loadImage(url){return new Promise((resolve,reject)=>{const image=new Image();image.crossOrigin='anonymous';image.decoding='async';image.onload=()=>image.naturalWidth>=600&&image.naturalHeight>=400?resolve(image):reject(new Error('BATHY_REFERENCE_IMAGE_DIMENSION_GATE'));image.onerror=()=>reject(new Error('BATHY_REFERENCE_IMAGE_DECODE_FAILED'));image.src=url})}
function imageSignal(image){const cv=document.createElement('canvas');cv.width=160;cv.height=128;const cx=cv.getContext('2d',{willReadFrequently:true});cx.drawImage(image,0,0,cv.width,cv.height);const d=cx.getImageData(0,0,cv.width,cv.height).data;let sum=0,sum2=0,n=0;for(let i=0;i<d.length;i+=16){const l=(.2126*d[i]+.7152*d[i+1]+.0722*d[i+2])/255;sum+=l;sum2+=l*l;n++}const mean=sum/n,std=Math.sqrt(Math.max(0,sum2/n-mean*mean));return{mean,std}}
async function loadReference(bounds){let last=null;for(const layer of GIBS_LAYERS){const url=wmsUrl(layer,bounds);try{const image=await loadImage(url),signal=imageSignal(image);if(signal.mean<.01||signal.std<.006)throw new Error(`BATHY_REFERENCE_SIGNAL:${signal.mean.toFixed(4)}:${signal.std.toFixed(4)}`);return Object.freeze({image,layer,url,signal})}catch(error){last=error}}throw new Error(`BATHY_REFERENCE_UNAVAILABLE:${last?.message||'unknown'}`)}
